def compute(vars):
    net_interest_income = vars["v1"]
    total_net_revenue = vars["v2"]

    if total_net_revenue == 0:
        return None

    ratio = net_interest_income / total_net_revenue
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "net_interest_income": net_interest_income,
            "total_net_revenue": total_net_revenue,
            "ratio": ratio,
            "percentage": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
